// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.skill.builtinimport com.roshan.persona.brain.intent.Intentimport com.roshan.persona.brain.skill.BrainSkillimport com.roshan.persona.brain.skill.InputTypeimport com.roshan.persona.brain.skill.SkillCapabilityimport com.roshan.persona.brain.skill.SkillContextimport com.roshan.persona.brain.skill.SkillOutputimport com.roshan.persona.brain.skill.SystemOperationimport com.roshan.persona.brain.skill.executor.SystemOperationExecutorimport com.roshan.persona.common.Resultimport javax.inject.Injectimport javax.inject.Singletonimport kotlin.reflect.KClass/** * NOUS — Built-in skills (Module 2 subset). * * These skills ship with the app and handle common intents. Each skill: *   1. Declares which intents it supports *   2. Declares required Android permissions *   3. Implements execute() to perform the action * * Full set (15+ skills) ships across Modules 2-13. Module 2 includes a * minimal set to demonstrate patterns: TorchSkill, CallSkill, SmsSkill, * OpenAppSkill, WebSearchSkill. */// ─── Torch skill ───────────────────────────────────────────────────────────@Singletonclass TorchSkill @Inject constructor(    private val systemExecutor: SystemOperationExecutor,) : BrainSkill {    override val id = "torch"    override val displayName = "Torch Control"    override val description = "Turn torch on or off"    override val capabilities = setOf(        SkillCapability("torch_control", "Turn torch on/off"),    )    override val requiredPermissions = emptySet<String>()    override val supportedIntents: Set<KClass<out Intent>> = setOf(        Intent.TorchOn::class,        Intent.TorchOff::class,    )    override suspend fun execute(intent: Intent, context: SkillContext): Result<SkillOutput> {        val operation = when (intent) {            is Intent.TorchOn -> SystemOperation.SetTorch(on = true)            is Intent.TorchOff -> SystemOperation.SetTorch(on = false)            else -> return Result.Success(                data = SkillOutput.Failure(                    error = com.roshan.persona.common.AppError.Skill.Crashed(                        skillName = id,                        cause = IllegalArgumentException("Unsupported intent: ${intent::class}"),                    ),                ),                correlationId = context.brainContext.correlationId,                durationNanos = 0,            )        }        val result = systemExecutor.execute(operation)        return when (result) {            is Result.Success -> Result.Success(                data = SkillOutput.Success(                    message = if (intent is Intent.TorchOn) "Torch on." else "Torch off.",                ),                correlationId = context.brainContext.correlationId,                durationNanos = 0,            )            is Result.Failure -> Result.Success(                data = SkillOutput.Failure(error = result.error),                correlationId = context.brainContext.correlationId,                durationNanos = 0,            )            is Result.Partial -> Result.Success(                data = SkillOutput.Partial(message = "Torch operation partial", warnings = result.warnings),                correlationId = context.brainContext.correlationId,                durationNanos = 0,            )        }    }}// ─── Volume skill ──────────────────────────────────────────────────────────@Singletonclass VolumeSkill @Inject constructor(    private val systemExecutor: SystemOperationExecutor,) : BrainSkill {    override val id = "volume"    override val displayName = "Volume Control"    override val description = "Adjust or set volume"    override val capabilities = setOf(        SkillCapability("volume_control", "Adjust volume up/down/set"),    )    override val requiredPermissions = emptySet<String>()    override val supportedIntents: Set<KClass<out Intent>> = setOf(        Intent.VolumeUp::class,        Intent.VolumeDown::class,        Intent.SetVolume::class,    )    override suspend fun execute(intent: Intent, context: SkillContext): Result<SkillOutput> {        val operation = when (intent) {            is Intent.VolumeUp -> SystemOperation.AdjustVolume(                delta = intent.amount ?: 1,                stream = com.roshan.persona.brain.skill.AudioStream.MEDIA,            )            is Intent.VolumeDown -> SystemOperation.AdjustVolume(                delta = -(intent.amount ?: 1),                stream = com.roshan.persona.brain.skill.AudioStream.MEDIA,            )            is Intent.SetVolume -> SystemOperation.SetVolume(                level = intent.level,                stream = com.roshan.persona.brain.skill.AudioStream.MEDIA,            )            else -> return Result.Success(                data = SkillOutput.Failure(                    error = com.roshan.persona.common.AppError.Skill.Crashed(                        skillName = id,                        cause = IllegalArgumentException("Unsupported intent"),                    ),                ),                correlationId = context.brainContext.correlationId,                durationNanos = 0,            )        }        val result = systemExecutor.execute(operation)        return when (result) {            is Result.Success -> {                val msg = when (intent) {                    is Intent.VolumeUp -> "Volume up."                    is Intent.VolumeDown -> "Volume down."                    is Intent.SetVolume -> "Volume set to ${intent.level}."                    else -> "Done."                }                Result.Success(                    data = SkillOutput.Success(message = msg),                    correlationId = context.brainContext.correlationId,                    durationNanos = 0,                )            }            is Result.Failure -> Result.Success(                data = SkillOutput.Failure(error = result.error),                correlationId = context.brainContext.correlationId,                durationNanos = 0,            )            is Result.Partial -> Result.Success(                data = SkillOutput.Partial(message = "Volume partial", warnings = result.warnings),                correlationId = context.brainContext.correlationId,                durationNanos = 0,            )        }    }}// ─── Call skill (requires permission) ──────────────────────────────────────@Singletonclass CallSkill @Inject constructor() : BrainSkill {    override val id = "call"    override val displayName = "Phone Call"    override val description = "Make a phone call"    override val capabilities = setOf(        SkillCapability("make_calls", "Initiate phone calls"),    )    override val requiredPermissions = setOf(        "android.permission.CALL_PHONE",        "android.permission.READ_CONTACTS",    )    override val supportedIntents: Set<KClass<out Intent>> = setOf(        Intent.Call::class,    )    override suspend fun execute(intent: Intent, context: SkillContext): Result<SkillOutput> {        val callIntent = intent as? Intent.Call            ?: return Result.Success(                data = SkillOutput.Failure(                    error = com.roshan.persona.common.AppError.Skill.Crashed(                        skillName = id,                        cause = IllegalArgumentException("Not a Call intent"),                    ),                ),                correlationId = context.brainContext.correlationId,                durationNanos = 0,            )        // If contact is null, ask for input (NeedsInput)        if (callIntent.contact.isNullOrBlank()) {            return Result.Success(                data = SkillOutput.NeedsInput(                    skillId = id,                    prompt = "Who do you want to call?",                    inputType = InputType.CONTACT,                ),                correlationId = context.brainContext.correlationId,                durationNanos = 0,            )        }        // Execute call via SystemOperation        val result = context.run {            // In real impl, we'd use SystemOperationExecutor injected here            // For Module 2, return success — Module 9 wires real executor            Result.Success(                data = SkillOutput.Success(                    message = "Calling ${callIntent.contact}.",                ),                correlationId = context.brainContext.correlationId,                durationNanos = 0,            )        }        return result    }}// ─── SMS skill (requires permission) ───────────────────────────────────────@Singletonclass SmsSkill @Inject constructor() : BrainSkill {    override val id = "send_sms"    override val displayName = "Send SMS"    override val description = "Send a text message"    override val capabilities = setOf(        SkillCapability("send_messages", "Send SMS messages"),    )    override val requiredPermissions = setOf(        "android.permission.SEND_SMS",        "android.permission.READ_CONTACTS",    )    override val supportedIntents: Set<KClass<out Intent>> = setOf(        Intent.SendSms::class,    )    override suspend fun execute(intent: Intent, context: SkillContext): Result<SkillOutput> {        val smsIntent = intent as? Intent.SendSms            ?: return Result.Success(                data = SkillOutput.Failure(                    error = com.roshan.persona.common.AppError.Skill.Crashed(                        skillName = id,                        cause = IllegalArgumentException("Not a SendSms intent"),                    ),                ),                correlationId = context.brainContext.correlationId,                durationNanos = 0,            )        // If contact is null, ask for input        if (smsIntent.contact.isNullOrBlank()) {            return Result.Success(                data = SkillOutput.NeedsInput(                    skillId = id,                    prompt = "Who do you want to text?",                    inputType = InputType.CONTACT,                ),                correlationId = context.brainContext.correlationId,                durationNanos = 0,            )        }        // If message is null, ask for input        if (smsIntent.message.isNullOrBlank()) {            return Result.Success(                data = SkillOutput.NeedsInput(                    skillId = id,                    prompt = "What message should I send to ${smsIntent.contact}?",                    inputType = InputType.TEXT,                ),                correlationId = context.brainContext.correlationId,                durationNanos = 0,            )        }        // Execute SMS send — Module 9 wires real executor        return Result.Success(            data = SkillOutput.Success(                message = "Message sent to ${smsIntent.contact}.",            ),            correlationId = context.brainContext.correlationId,            durationNanos = 0,        )    }}// ─── Open app skill ────────────────────────────────────────────────────────@Singletonclass OpenAppSkill @Inject constructor(    private val systemExecutor: SystemOperationExecutor,) : BrainSkill {    override val id = "open_app"    override val displayName = "Open App"    override val description = "Launch an application"    override val capabilities = setOf(        SkillCapability("open_apps", "Launch installed applications"),    )    override val requiredPermissions = emptySet<String>()    override val supportedIntents: Set<KClass<out Intent>> = setOf(        Intent.OpenApp::class,    )    override suspend fun execute(intent: Intent, context: SkillContext): Result<SkillOutput> {        val openIntent = intent as? Intent.OpenApp            ?: return Result.Success(                data = SkillOutput.Failure(                    error = com.roshan.persona.common.AppError.Skill.Crashed(                        skillName = id,                        cause = IllegalArgumentException("Not an OpenApp intent"),                    ),                ),                correlationId = context.brainContext.correlationId,                durationNanos = 0,            )        val packageName = openIntent.packageName            ?: return Result.Success(                data = SkillOutput.NeedsInput(                    skillId = id,                    prompt = "Which app should I open?",                    inputType = InputType.TEXT,                ),                correlationId = context.brainContext.correlationId,                durationNanos = 0,            )        val result = systemExecutor.execute(SystemOperation.OpenApp(packageName = packageName))        return when (result) {            is Result.Success -> Result.Success(                data = SkillOutput.Success(message = "Opening ${openIntent.appName ?: packageName}."),                correlationId = context.brainContext.correlationId,                durationNanos = 0,            )            is Result.Failure -> Result.Success(                data = SkillOutput.Failure(error = result.error),                correlationId = context.brainContext.correlationId,                durationNanos = 0,            )            is Result.Partial -> Result.Success(                data = SkillOutput.Partial(message = "Open app partial", warnings = result.warnings),                correlationId = context.brainContext.correlationId,                durationNanos = 0,            )        }    }}// ─── Brightness skill ──────────────────────────────────────────────────────@Singletonclass BrightnessSkill @Inject constructor(    private val systemExecutor: SystemOperationExecutor,) : BrainSkill {    override val id = "brightness"    override val displayName = "Brightness Control"    override val description = "Set display brightness"    override val capabilities = setOf(        SkillCapability("brightness_control", "Adjust display brightness"),    )    override val requiredPermissions = emptySet<String>()    override val supportedIntents: Set<KClass<out Intent>> = setOf(        Intent.SetBrightness::class,    )    override suspend fun execute(intent: Intent, context: SkillContext): Result<SkillOutput> {        val brightnessIntent = intent as? Intent.SetBrightness            ?: return Result.Success(                data = SkillOutput.Failure(                    error = com.roshan.persona.common.AppError.Skill.Crashed(                        skillName = id,                        cause = IllegalArgumentException("Not a SetBrightness intent"),                    ),                ),                correlationId = context.brainContext.correlationId,                durationNanos = 0,            )        val level = brightnessIntent.level.coerceIn(0, 100) / 100f  // 0.0-1.0        val result = systemExecutor.execute(            SystemOperation.SetDisplayBrightness(level = level)        )        return when (result) {            is Result.Success -> Result.Success(                data = SkillOutput.Success(message = "Brightness set to ${brightnessIntent.level}%."),                correlationId = context.brainContext.correlationId,                durationNanos = 0,            )            is Result.Failure -> Result.Success(                data = SkillOutput.Failure(error = result.error),                correlationId = context.brainContext.correlationId,                durationNanos = 0,            )            is Result.Partial -> Result.Success(                data = SkillOutput.Partial(message = "Brightness partial", warnings = result.warnings),                correlationId = context.brainContext.correlationId,                durationNanos = 0,            )        }    }}